<template>
  <section>
    <div class="page-heading"><div><div class="eyebrow">事实审核 / Human review</div><h1>售前客服工作台</h1><p>先核对风险与事实来源，再决定发送、转人工或解决。系统草稿不会自动发送。</p></div><el-button @click="refresh" :loading="loading">刷新队列</el-button></div>
    <el-alert v-if="error" type="error" :title="error" :closable="false" show-icon class="notice" />
    <div class="service-grid">
      <aside class="queue-panel panel">
        <div class="queue-tabs"><button :class="{active:queue==='waiting_review'}" @click="changeQueue('waiting_review')">待审核 <b>{{ reviewCount }}</b></button><button :class="{active:queue==='transferred'}" @click="changeQueue('transferred')">已转人工 <b>{{ transferCount }}</b></button></div>
        <div v-if="!items.length&&!loading" class="queue-empty">当前队列为空</div>
        <button v-for="item in items" :key="item.id" class="queue-row" :class="{active:selected?.id===item.id}" @click="select(item)">
          <span class="risk-dot" :class="item.last_risk_level||'unknown'"></span><span><b>{{ item.product?.name||`会话 #${item.id}` }}</b><small>{{ riskLabel(item.last_risk_level) }} · {{ item.last_customer_message||item.transfer_reason||'等待确认' }}</small></span><time>{{ shortTime(item.updated_at) }}</time>
        </button>
      </aside>
      <main v-if="selected" class="case-panel">
        <header class="case-header panel"><div><span class="case-id">CASE {{ selected.id }}</span><h2>{{ selected.product?.name||'售前咨询' }}</h2></div><div class="case-tags"><el-tag :type="riskType(latestDecision?.risk_level||selected.last_risk_level)" effect="dark">{{ riskLabel(latestDecision?.risk_level||selected.last_risk_level) }}</el-tag><el-tag effect="plain">{{ statusLabel(selected.status) }}</el-tag></div></header>
        <div class="case-columns">
          <section class="timeline-panel panel"><div class="section-title"><b>会话时间线</b><span>顾客消息与已发送回复</span></div><div class="timeline"><article v-for="message in visibleMessages" :key="message.id" class="timeline-item" :class="message.sender_type"><div class="timeline-marker"></div><div><small>{{ senderLabel(message.sender_type) }} · {{ shortTime(message.created_at) }}</small><p>{{ message.content }}</p></div></article></div></section>
          <aside class="evidence-stack">
            <section class="panel evidence"><div class="section-title"><b>风险判断</b><span>确定性规则优先</span></div><dl><dt>风险等级</dt><dd>{{ riskLabel(latestDecision?.risk_level||selected.last_risk_level) }}</dd><dt>决策</dt><dd>{{ latestDecision?.decision||'—' }}</dd><dt>命中原因</dt><dd>{{ latestDecision?.reason_code||selected.transfer_reason||'—' }}</dd></dl></section>
            <section class="panel evidence"><div class="section-title"><b>事实来源</b><span>不含成本、毛利与内部库存</span></div><div v-if="!selected.fact_sources.length" class="empty-source">没有可确认的事实来源</div><article v-for="(source,index) in selected.fact_sources" :key="index" class="source-row"><b>{{ source.source_type||'事实' }} #{{ source.source_object_id||'—' }}</b><code>{{ source.version||'未标注版本' }}</code><p>{{ source.field_summary||'未提供字段摘要' }}</p><time>{{ source.data_time||'未提供数据时间' }}</time></article></section>
          </aside>
        </div>
        <section v-if="selected.status==='waiting_review'" class="review-panel panel"><div class="section-title"><b>人工审核回复</b><span>原始草稿只读，发送前顾客不可见</span></div><div class="draft-grid"><div class="original-draft"><label>系统原始草稿 · 只读</label><p>{{ draftText||'系统未生成草稿，请人工依据事实回复或转人工。' }}</p></div><div><label>客服编辑后回复</label><el-input v-model="reply" type="textarea" :autosize="{minRows:5,maxRows:9}" maxlength="1000" show-word-limit placeholder="核对事实来源后编辑回复内容" /></div></div><div class="review-actions"><el-button type="danger" plain @click="openTransfer">转人工</el-button><el-button @click="resolve" :loading="working">标记已解决</el-button><el-button type="primary" :disabled="!reply.trim()" :loading="working" @click="sendReply">审核并发送</el-button></div></section>
        <section v-else class="resolution-bar panel"><span>{{ selected.status==='transferred'?'此会话已转入人工处理队列，不向顾客承诺响应时间。':'当前会话无需继续发送回复。' }}</span><div><el-button v-if="selected.status!=='resolved'" @click="resolve" :loading="working">标记已解决</el-button><el-button v-if="selected.status!=='transferred'" type="danger" plain @click="openTransfer">转人工</el-button></div></section>
      </main>
      <main v-else class="case-empty panel"><span>QUEUE</span><h2>选择一个待处理会话</h2><p>详情中只显示风险判断、可用事实来源和人工处理记录。</p></main>
    </div>
    <el-dialog v-model="transferOpen" title="转人工处理" width="440px"><p>转人工原因将写入审计。顾客端只显示固定等待提示，不承诺响应时间。</p><el-input v-model="transferReason" type="textarea" :rows="4" maxlength="300" placeholder="请填写转人工原因" /><template #footer><el-button @click="transferOpen=false">取消</el-button><el-button type="danger" :disabled="!transferReason.trim()" :loading="working" @click="transfer">确认转人工</el-button></template></el-dialog>
  </section>
</template>

<script setup lang="ts">
import { computed,onMounted,ref } from "vue";import { ElMessage } from "element-plus";import { errorMessage } from "../api/client";import { m3Api,type ConversationMessage,type RiskLevel,type ServiceConversation,type ServiceQueueItem } from "../api/milestone3";
const queue=ref<"waiting_review"|"transferred">("waiting_review"),items=ref<ServiceQueueItem[]>([]),selected=ref<ServiceConversation>(),reviewCount=ref(0),transferCount=ref(0),reply=ref(""),loading=ref(false),working=ref(false),error=ref(""),transferOpen=ref(false),transferReason=ref("");
const latestDecision=computed(()=>selected.value?.decisions[selected.value.decisions.length-1]);const draftText=computed(()=>typeof selected.value?.pending_draft==="string"?selected.value.pending_draft:selected.value?.pending_draft?.content||"");const visibleMessages=computed(()=>selected.value?.messages.filter(m=>m.message_type!=="draft")||[]);
function riskLabel(level?:RiskLevel){return ({low:"低风险",medium:"中风险",high:"高风险"})[level||"medium"]}function riskType(level?:RiskLevel){return ({low:"success",medium:"warning",high:"danger"})[level||"medium"] as "success"|"warning"|"danger"}function statusLabel(value:ServiceConversation["status"]){return ({open:"处理中",waiting_review:"等待审核",transferred:"已转人工",resolved:"已解决"})[value]}function senderLabel(sender:ConversationMessage["sender_type"]){return ({customer:"顾客",assistant:"事实助手",customer_service:"人工客服",system:"系统"})[sender]}function shortTime(value?:string){if(!value)return"—";const date=new Date(value);return Number.isNaN(date.getTime())?value:date.toLocaleString("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})}
async function refresh(){loading.value=true;error.value="";try{const [review,transferred]=await Promise.all([m3Api.listServiceConversations("waiting_review"),m3Api.listServiceConversations("transferred")]);reviewCount.value=review.length;transferCount.value=transferred.length;items.value=queue.value==="waiting_review"?review:transferred;if(selected.value){const latest=items.value.find(i=>i.id===selected.value?.id);selected.value=latest?await m3Api.getServiceConversation(latest.id):undefined;reply.value=draftText.value}}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function changeQueue(value:typeof queue.value){queue.value=value;selected.value=undefined;reply.value="";await refresh()}async function select(item:ServiceQueueItem){working.value=true;try{selected.value=await m3Api.getServiceConversation(item.id);reply.value=draftText.value}catch(e){error.value=errorMessage(e)}finally{working.value=false}}
async function sendReply(){if(!selected.value||!reply.value.trim())return;working.value=true;try{await m3Api.sendServiceReply(selected.value.id,reply.value.trim());selected.value=undefined;ElMessage.success("回复已由人工审核并发送");await refresh()}catch(e){error.value=errorMessage(e)}finally{working.value=false}}
function openTransfer(){transferReason.value=latestDecision.value?.reason_code||selected.value?.transfer_reason||"";transferOpen.value=true}async function transfer(){if(!selected.value||!transferReason.value.trim())return;working.value=true;try{await m3Api.transferServiceConversation(selected.value.id,transferReason.value.trim());transferOpen.value=false;selected.value=undefined;ElMessage.success("已转人工并记录原因");await refresh()}catch(e){error.value=errorMessage(e)}finally{working.value=false}}async function resolve(){if(!selected.value)return;working.value=true;try{await m3Api.resolveServiceConversation(selected.value.id);selected.value=undefined;ElMessage.success("会话已标记为解决");await refresh()}catch(e){error.value=errorMessage(e)}finally{working.value=false}}onMounted(refresh);
</script>

<style scoped>
.notice{margin-bottom:14px}.service-grid{display:grid;grid-template-columns:300px minmax(0,1fr);gap:18px}.queue-panel{padding:0;overflow:hidden;align-self:start}.queue-tabs{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line)}.queue-tabs button{border:0;background:#f5f7f5;padding:14px 8px;color:var(--muted);cursor:pointer}.queue-tabs button.active{background:#fff;color:var(--ink);box-shadow:inset 0 -3px var(--green)}.queue-tabs b{display:inline-grid;place-items:center;min-width:20px;height:20px;border-radius:20px;background:#e4ece7;margin-left:3px}.queue-row{width:100%;border:0;border-bottom:1px solid #e5ebe7;background:#fff;padding:14px 12px;display:grid;grid-template-columns:9px 1fr auto;gap:10px;text-align:left;align-items:start;cursor:pointer}.queue-row:hover,.queue-row.active{background:#eef5f1}.queue-row span:nth-child(2){display:grid;gap:4px}.queue-row small,.queue-row time{color:var(--muted);font-size:11px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.risk-dot{width:8px;height:8px;margin-top:5px;border-radius:50%;background:#8c9a94}.risk-dot.low{background:#1b896c}.risk-dot.medium{background:#d49316}.risk-dot.high{background:#bb4c3d}.queue-empty{padding:48px 20px;text-align:center;color:var(--muted)}.case-panel{display:grid;gap:14px;min-width:0}.case-header{display:flex;justify-content:space-between;align-items:center}.case-header h2{margin:4px 0 0;font-size:19px}.case-id{font:11px Georgia,serif;letter-spacing:.12em;color:var(--green)}.case-tags{display:flex;gap:8px}.case-columns{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.8fr);gap:14px}.section-title{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:16px}.section-title span{font-size:11px;color:var(--muted)}.timeline{display:grid;gap:16px}.timeline-item{display:grid;grid-template-columns:12px 1fr;gap:10px;position:relative}.timeline-item:not(:last-child):before{content:"";position:absolute;left:5px;top:12px;bottom:-20px;border-left:1px solid #cedbd4}.timeline-marker{width:11px;height:11px;border:2px solid #158167;background:#fff;border-radius:50%;z-index:1}.timeline-item.customer_service .timeline-marker{background:#173b2f}.timeline-item small{color:var(--muted)}.timeline-item p{margin:5px 0;padding:10px 12px;background:#f3f7f4;line-height:1.6;white-space:pre-wrap}.evidence-stack{display:grid;gap:14px;align-content:start}.evidence dl{display:grid;grid-template-columns:70px 1fr;gap:10px;margin:0;font-size:13px}.evidence dt{color:var(--muted)}.evidence dd{margin:0;overflow-wrap:anywhere}.source-row{padding:11px 0;border-top:1px solid #e2e9e5;display:grid;gap:4px;font-size:12px}.source-row:first-of-type{border-top:0}.source-row code{color:var(--green)}.source-row p{margin:0;color:#44564e}.source-row time,.empty-source{color:var(--muted);font-size:11px}.review-panel{border-left:4px solid var(--green)}.draft-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.draft-grid label{display:block;font-size:12px;color:var(--muted);margin-bottom:7px}.original-draft{background:#f3f6f4;padding:13px}.original-draft p{margin:0;white-space:pre-wrap;line-height:1.65}.review-actions,.resolution-bar{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.resolution-bar{margin-top:0;align-items:center;justify-content:space-between}.case-empty{min-height:440px;display:grid;place-content:center;text-align:center;color:var(--muted)}.case-empty span{font:12px Georgia,serif;letter-spacing:.18em;color:var(--green)}.case-empty h2{color:var(--ink);margin:9px 0 4px}.case-empty p{margin:0}@media(max-width:1050px){.service-grid{grid-template-columns:250px 1fr}.case-columns,.draft-grid{grid-template-columns:1fr}}@media(max-width:760px){.service-grid{grid-template-columns:1fr}.case-header,.resolution-bar{align-items:flex-start;display:grid}.case-tags{margin-top:10px}.review-actions{flex-wrap:wrap}}
</style>
